INSERT INTO public.gastroset_meal_description VALUES (1, 'Свиная вырезка с конкасе из томатов');
INSERT INTO public.gastroset_meal_description VALUES (1, 'Картофельный мусс с маринованной цветной капустой');
INSERT INTO public.gastroset_meal_description VALUES (1, 'Каннеллони с мясом оленя и лесными грибами');
INSERT INTO public.gastroset_meal_description VALUES (1, 'Мороженое из лисичек с печеньем из тимьяна и лисичкой в горьком шоколаде');
INSERT INTO public.gastroset_meal_description VALUES (1, 'Хумус с маринованными мидиями');
INSERT INTO public.gastroset_meal_description VALUES (2, 'Пышные оладьи с томленой свининой и соусом из вершков');
INSERT INTO public.gastroset_meal_description VALUES (2, 'Картофельные шанешки с куриной котлетой и овощным тартаром');
INSERT INTO public.gastroset_meal_description VALUES (2, 'Закуска с куриной тапенадой и сельским наполеоном');
INSERT INTO public.gastroset_meal_description VALUES (2, 'Криспи драники с домашними шкварками и луком');
INSERT INTO public.gastroset_meal_description VALUES (2, 'Цезарь-карпаччо');
INSERT INTO public.gastroset_meal_description VALUES (2, 'Домашняя творожная запеканка с ягодным соусом');
INSERT INTO public.gastroset_meal_description VALUES (3, 'Кукурузный чаудер');
INSERT INTO public.gastroset_meal_description VALUES (3, 'Тартар из лосося с муссом из рикотты на французском хлебе');
INSERT INTO public.gastroset_meal_description VALUES (3, 'Ризотто том ям с филе фермерского цыплёнка');
INSERT INTO public.gastroset_meal_description VALUES (3, 'Медальоны из говядины с луковым соусом "капучино", сырным пюре и домашними томатами черри');
INSERT INTO public.gastroset_meal_description VALUES (3, 'Тыквенный мусс с шоколадно-вафельной крошкой и облепиховым гелем');
INSERT INTO public.gastroset_meal_description VALUES (4, 'Брускетта с тартаром из говядины и ремуладом');
INSERT INTO public.gastroset_meal_description VALUES (4, 'Печеные баклажаны с финиковым и орехово-кунжутным соусом');
INSERT INTO public.gastroset_meal_description VALUES (4, 'Осенний салат с цукини гриль, печеной тыквой и мягким сыром');
INSERT INTO public.gastroset_meal_description VALUES (4, 'Куриный ролл со сливочно-мятным булгуром');
INSERT INTO public.gastroset_meal_description VALUES (4, 'Томленые говяжьи щеки с пюре из корнеплодов и шоколадным демигласом');
INSERT INTO public.gastroset_meal_description VALUES (4, 'Лимонный чизкейк');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Бургер с говядиной, сыром моцарелла, хрустящими начос, свежим томатом, луком, салатом и фирменным соусом');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Бургер с цыпленком гриль, копченым беконом, сыром моцарелла, свежим томатом, листом салата и соусом «бургер»');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Бургер с жареным сыром моцарелла, устричным соусом, свежим томатом и салатом');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Крылышки в хрустящей панировке в BBQ глазури и с соусом спайси');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Королевские креветки в кимчи глазури на хрустящей лапше');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Тапас с тартаром из говядины, BBQ заправкой и луком фризл');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Тапас с тапенадой из фирменных маслин и оливок и муссом из рикотты');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Тапас с цыпленком, вяленым томатом, рикоттой и горчичным соусом');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Картофель по-деревенски с сырным соусом');
INSERT INTO public.gastroset_meal_description VALUES (5, 'Фирменные огурцы');
INSERT INTO public.gastroset_meal_description VALUES (6, 'Салат с копчеными мидиями');
INSERT INTO public.gastroset_meal_description VALUES (6, 'Суп «Бостон чаудер» с креветками, кальмаром и форелью');
INSERT INTO public.gastroset_meal_description VALUES (6, 'Датский хот-дог с колбаской из форели и трески');
INSERT INTO public.gastroset_meal_description VALUES (6, 'Фри из трех видов картофеля с трюфельным соусом');
INSERT INTO public.gastroset_meal_description VALUES (6, 'Рийет из макрели с чипсами из водорослей и рисовой бумаги');
INSERT INTO public.gastroset_meal_description VALUES (6, 'Моти с лесными ягодами, моти с манго-чиа и моти с зеленым яблоком с джемом');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Верхний ярус:');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Бургер с курицей и беконом со сладким чили');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Кукуруза гриль в чесночном айоли с пармезаном');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Карамелизированный лайм');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Шампиньоны на шампуре в чесночном соусе с травами');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Шампиньоны на шампуре с паприкой и сладким чили');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Томленые ребра в пикантной глазури барбекю с хрустящим луком');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Колбаски барбекю');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Нижний ярус:');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Куриные крылья баффало с глазурью, с перцем халапеньо и чили');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Запеченный картофель с песто из томатов, чесночным соусом и травами');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Овощное соте в соусе маринара');
INSERT INTO public.gastroset_meal_description VALUES (7, 'Огурцы пикули');
INSERT INTO public.gastroset_meal_description VALUES (8, 'Том Ям с морепродуктами');
INSERT INTO public.gastroset_meal_description VALUES (8, 'Паста Фетучини с морепродуктами');
INSERT INTO public.gastroset_meal_description VALUES (8, 'Ролл Филадельфия в кунжуте');
INSERT INTO public.gastroset_meal_description VALUES (8, 'Салат с курицей в азиатском стиле');
INSERT INTO public.gastroset_meal_description VALUES (8, 'Шоколадный японский чизкейк');
INSERT INTO public.gastroset_meal_description VALUES (9, 'Салат с куриным филе, апельсином, сезонной зеленью в апельсиново-горчичном соусе');
INSERT INTO public.gastroset_meal_description VALUES (9, 'Брускетта с томленой печенью');
INSERT INTO public.gastroset_meal_description VALUES (9, 'Брускетта с лисичками');
INSERT INTO public.gastroset_meal_description VALUES (9, 'Брускетта с пряной говядиной');
INSERT INTO public.gastroset_meal_description VALUES (9, 'Драники с томленой рулькой');
INSERT INTO public.gastroset_meal_description VALUES (9, 'Яблоко запеченное с клубникой и пломбиром');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Дранбургер с индейкой (бургер из домашних драников с сочной котлетой из мякоти индейки, хрустящим салатом, свежим помидором и солёным бочковым огурцом)');
INSERT INTO public.gastroset_meal_description VALUES (46, 'Соус чесночный');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Толстые медово-горчичные рёбра');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Фирменные маринованные уши');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Папричные шашлычки из фермерской свинины');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Пышки в сметанном креме с клубничным вареньем «как у бабушки»');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Домашние соленья: маринованные помидоры и бочковые солёные огурцы');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Картофельные дольки по-деревенски');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Морковь фри');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Клюква дикорастущая');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Зелень');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Аджика по дедушкиному рецепту');
INSERT INTO public.gastroset_meal_description VALUES (10, 'Острый чесночный соус');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Салат «Ацецили» (жареные баклажаны, заправленные грецким орехом, томатами, салатом, репчатым луком и пикантной красной фасолью, с добавлением грузинских специй и свежей зелени)');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Салат «Брокколи» (бланшированная брокколи, замаринованная в винном уксусе, подается с маринованной морковью и чесноком)');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Пхали (отварные овощи, морковь, свекла, стручковая фасоль перетертая с грецким орехом и чесноком)');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Борани (кусочки свинины, томленые в красном сухом вине с жареными ломтиками кабачка, томатами и шампиньонами, подается с соусом Наршараб)');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Чебурек казан (огромный чебурек с начинкой из мелкорубленной говядины и свинины, приправленная кинзой и ароматными специями)');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Кабаби из птицы (сочные колбаски из рубленой птицы и свинины, запеченные с грузинскими специями, луком и сумахом, подаётся на тонком лаваше)');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Соус сацибели (классический грузинский острый соус из томата с чесноком и специями)');
INSERT INTO public.gastroset_meal_description VALUES (11, 'Мильфей лимонный (пирожное из слоеного теста со сливочным кремом и лимонным конфитюром)');
INSERT INTO public.gastroset_meal_description VALUES (12, 'Фуа-гра из куриной печени в ягодном соусе с карамелизированным луком');
INSERT INTO public.gastroset_meal_description VALUES (12, 'Баклажаны аля пармиджано');
INSERT INTO public.gastroset_meal_description VALUES (12, 'Ребра с картофельными пончиками под коньяком с корицей');
INSERT INTO public.gastroset_meal_description VALUES (12, 'Брауни с соленой карамелью и мороженым');
INSERT INTO public.gastroset_meal_description VALUES (12, 'Брауни с кремом шоколадный чизкейк');
INSERT INTO public.gastroset_meal_description VALUES (12, 'Чиабатта');
INSERT INTO public.gastroset_meal_description VALUES (13, 'Сет закусок:- эклер с рикоттой и вялеными томатами;- эклер с голландским соусом и лососем гравлакс;- эклер с тыквой, спаржей и голубым сыром');
INSERT INTO public.gastroset_meal_description VALUES (13, 'Суп из тыквы с кокосовым молоком и копченой уткой');
INSERT INTO public.gastroset_meal_description VALUES (13, 'Салат из руколы с фенхелем, яблоком и облепиховым кремом');
INSERT INTO public.gastroset_meal_description VALUES (13, 'Рулет из индейки со шпинатом, морковным муссом и чечевицей');
INSERT INTO public.gastroset_meal_description VALUES (13, 'Тарталетка "Капучино с кешью"');
INSERT INTO public.gastroset_meal_description VALUES (14, 'Лосось в грибном соусе из белого вина со стручковой фасолью');
INSERT INTO public.gastroset_meal_description VALUES (14, 'Креветки в сливочном соусе');
INSERT INTO public.gastroset_meal_description VALUES (14, 'Мидии в ракушках в итальянском соусе');
INSERT INTO public.gastroset_meal_description VALUES (14, 'Улитки в раковине в соусе Версаль');
INSERT INTO public.gastroset_meal_description VALUES (15, 'Запеченный баклажан с сыром');
INSERT INTO public.gastroset_meal_description VALUES (15, 'Суп-крем из тыквы с острым арахисом');
