INSERT INTO public.gastroset_meal_description VALUES (127, 'Аджарский хачапури с начинкой из двух сыров и яйцом');
INSERT INTO public.gastroset_meal_description VALUES (127, 'Кукуруза на подушке из морепродуктов');
INSERT INTO public.gastroset_meal_description VALUES (127, 'Шашлык «Батумский городской» (себеп кабаби из курицы укутанное в мясо свинины)');
INSERT INTO public.gastroset_meal_description VALUES (127, 'Хинкали с картошкой и грибами с добавлением эстрагона');
INSERT INTO public.gastroset_meal_description VALUES (127, 'Пахлава (тончайшие слои теста, пропитанные медовым сиропом с фисташковым кремом на основе крем чиза с кунжутом)');
INSERT INTO public.gastroset_meal_description VALUES (128, 'Запеченный на костре картофель с грудинкой и чесночным дипом');
INSERT INTO public.gastroset_meal_description VALUES (128, 'Пате из куриной печени с клюквенно-розмариновым конфитюром на бородинском хлебе');
INSERT INTO public.gastroset_meal_description VALUES (128, 'Овощи, запечённые на гриле, с соусом пилати и дзадзики');
INSERT INTO public.gastroset_meal_description VALUES (128, 'Каша из котелка лесника с белыми грибами и рваной говядиной');
INSERT INTO public.gastroset_meal_description VALUES (128, 'Ростбиф на огне с малиновым луком, домашним чесночным соусом и лепешкой');
INSERT INTO public.gastroset_meal_description VALUES (128, 'То самое маршмеллоу');
INSERT INTO public.gastroset_meal_description VALUES (129, 'Говяжьи щечки с трюфельным пюре');
INSERT INTO public.gastroset_meal_description VALUES (129, 'Севиче с лососем по-перуански');
INSERT INTO public.gastroset_meal_description VALUES (129, 'Японский суп-лапша чука соба');
INSERT INTO public.gastroset_meal_description VALUES (129, 'Оливье по-нарочански с копченым угрем и унаги-заправкой');
INSERT INTO public.gastroset_meal_description VALUES (129, 'Шоколадный фондан с крем-фреш соусом');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Запеченная свинина «по-французски»');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Печеный картофель со свежим укропом и петрушкой');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Классический салат «Оливье» с докторской колбасой');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Салат «Селедочка под шубой»');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Рулетики из ветчины с сырной начинкой');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Бутерброды со шпротами и сыром');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Тарталетки с икрой');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Консервированные томаты и огурцы');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Маринованная капуста');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Шоколадные грибочки');
INSERT INTO public.gastroset_meal_description VALUES (130, 'Конфеты «Как в детстве»');
INSERT INTO public.gastroset_meal_description VALUES (131, '“Разговоры у огня” — тартар из говядины с муссом из печеного чеснока, бородинским чипсом и бочковым огурцом');
INSERT INTO public.gastroset_meal_description VALUES (131, '“Вкус детства” — крем-суп из белых грибов с гренками и зеленым соусом');
INSERT INTO public.gastroset_meal_description VALUES (131, '“Главный герой вечера” — стейк из свиной шеи с пюре из тыквы, мясным соусом, вяленой брусникой и луковым джемом');
INSERT INTO public.gastroset_meal_description VALUES (131, '“Сладкая искра” — шарлотка с соленой карамелью, пломбиром, клюквой и розмарином');
INSERT INTO public.gastroset_meal_description VALUES (132, 'Том Ям Кай с цыплёнком су-вид и кокосовыми сливками');
INSERT INTO public.gastroset_meal_description VALUES (132, 'Лапша Харусамэ Куроганэ-эби с креветками и диппинг-соусом');
INSERT INTO public.gastroset_meal_description VALUES (132, 'Ролл с крабовым муссом, японской маринованной редькой и соусами свит чили и терияки');
INSERT INTO public.gastroset_meal_description VALUES (132, 'Ролл Радуга с тремя видами рыбы');
INSERT INTO public.gastroset_meal_description VALUES (132, 'Ролл классика Японии с норвежской форелью и авокадо');
INSERT INTO public.gastroset_meal_description VALUES (133, 'Овощной тартар со сливочным раком и заправкой винегрет');
INSERT INTO public.gastroset_meal_description VALUES (133, 'Куриное суфле "А-ля Веллингтон" со сливочной креветкой');
INSERT INTO public.gastroset_meal_description VALUES (133, 'Лукошко из картошки с лесными грибами');
INSERT INTO public.gastroset_meal_description VALUES (133, 'Сфольятелла с кокосовым муссом и манговым кули');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Нью-Йорк (классический четвертьфунтовый чизбургер с сочной крафтовой говяжьей котлетой и сыром)');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Кентукки (куриные чупа чупсы в пикантной глазури)');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Теннеси (томленые ребра в глазури Джек Дэниэлс с сырным попкорном)');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Канзас (пулд порк сэндвич с двойным сыром)');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Техас (колбаски гриль с соусом «Каролина рипер» и криспи луком)');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Зона 51 (уфо сэндвич с хрустящим беконом, сыром чеддер и соусом ранч)');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Лас-Вегас (пинчос с пепперони, сыром чеддер и огурчиками пикули)');
INSERT INTO public.gastroset_meal_description VALUES (134, 'Лос-Анджелес (чизкейк «Аллея славы» в виде звезды)');
INSERT INTO public.gastroset_meal_description VALUES (135, '“Огород и грядки” — брускетта с паштетом, яблоком и укропной пудрой');
INSERT INTO public.gastroset_meal_description VALUES (135, '“Аромат печи” — драники с кремом из сметаны, грибами и грудинкой');
INSERT INTO public.gastroset_meal_description VALUES (135, '“Запах костра” — свиные ребрышки с морковным пюре и облепиховым BBQ');
INSERT INTO public.gastroset_meal_description VALUES (135, '“Сладкая банка из погреба” — чернично-лавандовый трайфл с маршмеллоу');
